grammar MAPL;

mapUnit
    : mapDecl* EOF
    ;

mapDecl
    : 'map' IDENT 'from' IDENT 'to' IDENT ';' mapBody 'end' ';'
    ;

mapBody
    : mapStmt*
    ;

mapStmt
    : assignStmt
    | assignDefaultStmt
    | functionAssignStmt
    | ifStmt
    | forStmt
    | validateStmt
    ;

fieldPath
    : IDENT ('.' IDENT)*
    ;

assignStmt
    : fieldPath ':=' fieldPath ';'
    ;

assignDefaultStmt
    : fieldPath ':=' fieldPath 'default' expr ';'
    ;

functionAssignStmt
    : fieldPath ':=' functionCall ';'
    ;

functionCall
    : IDENT '(' exprList? ')'
    ;

ifStmt
    : 'if' expr 'then' mapBody ('else' mapBody)? 'end' ';'
    ;

forStmt
    : 'for' 'each' fieldPath 'as' IDENT mapBody 'end' ';'
    ;

validateStmt
    : 'validate' expr ';'
    ;

exprList
    : expr (',' expr)*
    ;

expr
    : logicalOrExpr
    ;

logicalOrExpr
    : logicalAndExpr ('or' logicalAndExpr)*
    ;

logicalAndExpr
    : equalityExpr ('and' equalityExpr)*
    ;

equalityExpr
    : relationalExpr (('=' | '<>') relationalExpr)*
    ;

relationalExpr
    : additiveExpr (('<' | '<=' | '>' | '>=') additiveExpr)*
    ;

additiveExpr
    : multiplicativeExpr (('+' | '-') multiplicativeExpr)*
    ;

multiplicativeExpr
    : unaryExpr (('*' | '/' | 'mod') unaryExpr)*
    ;

unaryExpr
    : ('not' | '-') unaryExpr

qualifiedName '(' exprList? ')'
