program MutualRecursionEvenOdd;

var
  parity: integer;

procedure IsEven(n: integer);
begin
  if n = 0 then
    parity := 1
  else
    IsOdd(n - 1)
end;

procedure IsOdd(n: integer);
begin
  if n = 0 then
    parity := 0
  else
    IsEven(n - 1)
end;

procedure PrintChecks(i, max: integer);
begin
  if i <= max then
  begin
    IsEven(i);
    writeln('even(', i, ')=', parity);
    IsOdd(i);
    writeln('odd(', i, ')=', parity);
    PrintChecks(i + 1, max)
  end
end;

begin
  PrintChecks(0, 11)
end.

program RecursiveFactorial;

procedure PrintFactRange(i, max, acc: integer);
begin
  if i <= max then
  begin
    writeln('fact(', i, ')=', acc);
    PrintFactRange(i + 1, max, acc * (i + 1))
  end
end;

begin
  PrintFactRange(0, 10, 1)
end.

program RecursiveFibonacci;

procedure PrintFibRange(i, max, a, b: integer);
begin
  if i < max then
  begin
    writeln('fib(', i, ')=', a);
    PrintFibRange(i + 1, max, b, a + b)
  end
end;

begin
  PrintFibRange(0, 12, 0, 1)
end.

